#requires -Version 5.1
[CmdletBinding()]
param()
# Read-only only. No backup claim or DELETE instruction is generated by this preview.
$ErrorActionPreference='Stop'
$stage='load-native-runner'
try {
 . (Join-Path $PSScriptRoot 'diagnose-gre-series.ps1')
 $stage='postgres-discovery'
 $answer=Invoke-GreSeriesDocker -Arguments @('--context','desktop-linux','ps','--filter','label=com.docker.compose.project=factuez-san-jose-test','--filter','label=com.docker.compose.service=postgres','--format','{{.ID}}')
 if($answer.exitCode -ne 0){throw 'DISCOVERY_FAILED'}
 $ids=@($answer.stdout -split '\r?\n'|Where-Object{$_.Trim().Length -gt 0})
 if($ids.Count -ne 1 -or $ids[0] -cnotmatch '^[a-f0-9]{12,64}$'){throw 'EXACT_POSTGRES_REQUIRED'}
 $stage='read-only-preview'
 $sql=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'gre-series-cleanup-preflight.sql'))
 $answer=Invoke-GreSeriesDocker -Arguments @('--context','desktop-linux','exec','-i',$ids[0],'psql','-X','--no-password','-qAt','-v','ON_ERROR_STOP=1','-U','postgres','-d','factuez_billing') -InputText $sql
 if($answer.exitCode -ne 0){throw 'PREVIEW_FAILED'}
 $rows=@($answer.stdout -split '\r?\n'|Where-Object{$_.Trim().StartsWith('{')})
 if($rows.Count -ne 1){throw 'PREVIEW_INVALID'}
 $preview=$rows[0]|ConvertFrom-Json
 if($preview.version -cne 'factuez.gre-series-cleanup-preview.v2' -or $preview.issuerRuc -cne '20600979630' -or $preview.preflightOnly -ne $true){throw 'PREVIEW_INVALID'}
 $canonical=$preview|ConvertTo-Json -Depth 10 -Compress
 $hash=[Security.Cryptography.SHA256]::Create()
 try{$sha=([BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical)))).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose()}
 [pscustomobject]@{status='preview-only';reviewSha256=$sha;snapshot=$preview}|ConvertTo-Json -Depth 12 -Compress
}catch{
 [pscustomobject]@{status='failed';stage=$stage;code='GRE_CLEANUP_PREFLIGHT_FAILED'}|ConvertTo-Json -Compress
 exit 1
}
